// Intersperse takes a slice of integers and an integer delimiter,
// and returns a new slice with the delimiter interspersed between each pair of consecutive elements.
// Example usage:
// >>> Intersperse([]int{5, 6, 3, 2}, 8)
// []int{5, 8, 6, 8, 3, 8, 2}
// >>> Intersperse([]int{}, 7)
// []
// >>> Intersperse([]int{2, 2, 2}, 2)
// []int{2, 2, 2, 2, 2}
func Intersperse(numbers []int, delimeter int) []int {
	result := make([]int, 0)
	if len(numbers) == 0 {
		return result
	}
	for i := 0; i < len(numbers)-1; i++ {
		n := numbers[i]
		result = append(result, n)
		result = append(result, delimeter)
	}
	result = append(result, numbers[len(numbers)-1])
	return result
}

func TestIntersperse(t *testing.T) {
	assert := assert.New(t)
	assert.Equal([]int{}, Intersperse([]int{}, 7))
	assert.Equal([]int{5, 8, 6, 8, 3, 8, 2}, Intersperse([]int{5, 6, 3, 2}, 8))
	assert.Equal([]int{2, 2, 2, 2, 2}, Intersperse([]int{2, 2, 2}, 2))
}
