// SumProduct calculates the sum and product of all integers in the given slice.
// It returns a slice containing the sum and product as two elements.
//
// Examples:
// >>> SumProduct([]int{})
// [2]int{0, 1}
// >>> SumProduct([]int{1, 1, 1})
// [2]int{3, 1}
// >>> SumProduct([]int{100, 0})
// [2]int{100, 0}
// >>> SumProduct([]int{3, 5, 7})
// [2]int{15, 105}
// >>> SumProduct([]int{10})
// [2]int{10, 10}
func SumProduct(numbers []int) [2]int {
	sum_value := 0
	prod_value := 1

	for _, n := range numbers {
		sum_value += n
		prod_value *= n
	}
	return [2]int{sum_value, prod_value}
}

// TestSumProduct checks the correctness of the SumProduct function with various test cases.
func TestSumProduct(t *testing.T) {
	assert := assert.New(t)
	assert.Equal([2]int{0, 1}, SumProduct([]int{}))
	assert.Equal([2]int{3, 1}, SumProduct([]int{1, 1, 1}))
	assert.Equal([2]int{100, 0}, SumProduct([]int{100, 0}))
	assert.Equal([2]int{3 + 5 + 7, 3 * 5 * 7}, SumProduct([]int{3, 5, 7}))
	assert.Equal([2]int{10, 10}, SumProduct([]int{10}))
