func Factorize(n int) []int {
    fact := make([]int, 0)
    for i := 2; i <= int(math.Sqrt(float64(n))); i++ {
        if n%i == 0 {
            fact = append(fact, i)
            n /= i
        } else {
            i++
        }
    }
    if n > 1 {
        fact = append(fact, n)
    }
    return fact
}

func main() {
    fmt.Println(Factorize(2)) // Output: [2]
    fmt.Println(Factorize(4)) // Output: [2, 2]
    fmt.Println(Factorize(8)) // Output: [2, 2, 2]
    fmt.Println(Factorize(3 * 19)) // Output: [3, 19]
    fmt.Println(Factorize(3 * 19 * 3 * 19)) // Output: [3, 3, 19, 19]
    fmt.Println(Factorize(3 * 19 * 3 * 19 * 3 * 19)) // Output: [3, 3, 3, 19, 19, 19]
    fmt.Println(Factorize(3 * 19, 19)) // Output: [3, 19, 19, 19]
    fmt.Println(Factorize(3 * 2 * 3)) // Output: [2, 3, 3]
