package main

import (
	"testing"
)

// Monotonic checks if a slice of integers is monotonic.
// A slice is monotonic if it is either entirely non-increasing or non-decreasing.
// Examples:
// >>> Monotonic([]int{1, 2, 4, 10})
// true
// >>> Monotonic([]int{1, 2, 4, 20})
// true
// >>> Monotonic([]int{1, 20, 4, 10})
// false
// >>> Monotonic([]int{4, 1, 0, -10})
// true
// >>> Monotonic([]int{4, 1, 1, 0})
// true
// >>> Monotonic([]int{1, 2, 3, 2, 5, 60})
// false
// >>> Monotonic([]int{1, 2, 3, 4, 5, 60})
// true
// >>> Monotonic([]int{9, 9, 9, 9})
// true
func Monotonic(l []int) bool {
	if len(l) <= 1 {
		return true
	}

	var increasing bool
	for i := 0; i < len(l)-1; i++ {
		if l[i] == l[i+1] {
			continue
		}
		if increasing && l[i] > l[i+1] {
			return false
		}
		if !increasing && l[i] < l[i+1] {
			return false
		}
		increasing = l[i] < l[i+1]
	}

	return true
}

func TestMonotonic(t *testing.T) {
	assert := assert.New(t)
	assert.Equal(true, Monotonic([]int{1, 2, 4, 10}))
	assert.Equal(true, Monotonic([]int{1, 2, 4, 20}))
	assert.Equal(false, Monotonic([]int{1, 20, 4, 10}))
	assert.Equal(true, Monotonic([]int{4, 1, 0, -10}))
	assert.Equal(true, Monotonic([]int{4, 1, 1, 0}))
	assert.Equal(false, Monotonic([]int{1, 2, 3, 2, 5, 60}))
	assert.Equal(true, Monotonic([]int{1, 2, 3, 4, 5, 60}))
	assert.Equal(true, Monotonic([]int{9, 9, 9, 9}))
}
