// F(0) = 0, F(1) = 1, F(2) = 2, and for n > 2, F(n) = F(n-1) + F(n-2) + F(n-3).
// This function uses memoization to optimize the recursive calls.
func Fibfib(n int) int {
	if n <= 0 {
		return 0
	}
	memo := make(map[int]int)
	return fibfibMemo(n, memo)
}

// fibfibMemo is a helper function that uses memoization to calculate the nth Fibonacci number.
func fibfibMemo(n int, memo map[int]int) int {
	if n == 0 || n == 1 || n == 2 {
		return n
	}
	if _, exists := memo[n]; !exists {
		memo[n] = fibfibMemo(n-1, memo) + fibfibMemo(n-2, memo) + fibfibMemo(n-3, memo)
	}
	return memo[n]
}

func TestFibfib(t *testing.T) {
	assert := assert.New(t)
	assert.Equal(1, Fibfib(2))
	assert.Equal(0, Fibfib(1))
	assert.Equal(4, Fibfib(5))
	assert.Equal(24, Fibfib(8))
	assert.Equal(81, Fibfib(10))
	assert.Equal(274, Fibfib(12))
	assert.Equal(927, Fibfib(14))
}
