// TriangleArea calculates the area of a triangle given its side lengths.
// It returns the area rounded to two decimal places if the sides form a valid triangle,
// otherwise it returns -1.
//
// Examples:
// >>> TriangleArea(3, 4, 5)
// 6.00
// >>> TriangleArea(1, 2, 10)
// -1
// >>> TriangleArea(4, 8, 5)
// 8.18
// >>> TriangleArea(2, 2, 2)
// 1.73
// >>> TriangleArea(1, 2, 3)
// -1
// >>> TriangleArea(10, 5, 7)
// 16.25
// >>> TriangleArea(2, 6, 3)
// -1
// >>> TriangleArea(1, 1, 1)
// 0.43
// >>> TriangleArea(2, 2, 10)
// -1
func TriangleArea(a float64, b float64, c float64) interface{} {
    if a+b <= c || a+c <= b || b+c <= a {
        return -1
    }
    s := (a + b + c) / 2
    area := math.Sqrt(s * (s - a) * (s - b) * (s - c))
    area = math.Round(area*100) / 100
    return area
}

// TestTriangleArea tests the TriangleArea function with various inputs.
func TestTriangleArea(t *testing.T) {
    assert := assert.New(t)
    assert.Equal(6.00, TriangleArea(3, 4, 5))
    assert.Equal(-1, TriangleArea(1, 2, 10))
    assert.Equal(8.18, TriangleArea(4, 8, 5))
    assert.Equal(1.73, TriangleArea(2, 2, 2))
    assert.Equal(-1, TriangleArea(1, 2, 3))
    assert.Equal(16.25, TriangleArea(10, 5, 7))
    assert.Equal(-1, TriangleArea(2, 6, 3))
    assert.Equal(0.43, TriangleArea(1, 1, 1))
    assert.Equal(-1, TriangleArea(2, 2, 10))
}
