		for i := 0; i < int(math.Pow(float64(n), 0.5)+1); i++ {
			if n%i == 0 {
				return false
			}
		}
		return true
	}
	for i := 2; i < 101; i++ {
		if !isPrime(i) {
			continue
		}
		for j := i + 1; j < 101; j++ { // Start from i+1 to avoid duplicate checks
			if !isPrime(j) {
				continue
			}
			for k := j + 1; k < 101; k++ { // Start from j+1 to avoid duplicate checks
				if !isPrime(k) {
					continue
				}
				if i*j*k == a {
					return true
				}
			}
		}
	}
	return false
}

