// IsSimplePower checks if x is a simple power of n.
// A number x is a simple power of n if there exists an integer k such that x = n^k.
// For example, IsSimplePower(1, 4) returns true because 1 = 4^0.
// IsSimplePower(2, 2) returns true because 2 = 2^1.
// IsSimplePower(8, 2) returns true because 8 = 2^3.
// IsSimplePower(3, 2) returns false because there is no integer k such that 3 = 2^k.
// IsSimplePower(3, 1) returns false because 3 is not a power of 1.
// IsSimplePower(5, 3) returns false because there is no integer k such that 5 = 3^k.
// IsSimplePower(16, 2) returns true because 16 = 2^4.
// IsSimplePower(143214, 16) returns false because there is no integer k such that 143214 = 16^k.
// IsSimplePower(4, 2) returns true because 4 = 2^2.
// IsSimplePower(9, 3) returns true because 9 = 3^2.
// IsSimplePower(16, 4) returns true because 16 = 4^2.
// IsSimplePower(24, 2) returns false because there is no integer k such that 24 = 2^k.
// IsSimplePower(128, 4) returns false because there is no integer k such that 128 = 4^k.
// IsSimplePower(12, 6) returns false because there is no integer k such that 12 = 6^k.
// IsSimplePower(1, 1) returns true because 1 = 1^1.
// IsSimplePower(1, 12) returns true because 1 = 12^0.
func IsSimplePower(x int, n int) bool {
	if x == 1 {
		return true
	}
	if n == 1 {
		return false
	}
	if x%n != 0 {
		return false
	}
	if x < n {
		return false
	}
	return IsSimplePower(x/n, n)
}

func TestIsSimplePower(t *testing.T) {
	assert := assert.New(t)
	assert.Equal(true, IsSimplePower(1, 4))
	assert.Equal(true, IsSimplePower(2, 2))
	assert.Equal(true, IsSimplePower(8, 2))
	assert.Equal(false, IsSimplePower(3, 2))
	assert.Equal(false, IsSimplePower(3, 1))
	assert.Equal(false, IsSimplePower(5, 3))
	assert.Equal(true, IsSimplePower(16, 2))
	assert.Equal(false, IsSimplePower(143214, 16))
	assert.Equal(true, IsSimplePower(4, 2))
	assert.Equal(true, IsSimplePower(9, 3))
	assert.Equal(true, IsSimplePower(16, 4))
	assert.Equal(false, IsSimplePower(24, 2))
	assert.Equal(false, IsSimplePower(128, 4))
	assert.Equal(false, IsSimplePower(12, 6))
	assert.Equal(true, IsSimplePower(1, 1))
	assert.Equal(true, IsSimplePower(1, 12))
}

