// AntiShuffle takes a string and returns a new string where each word's characters are sorted.
// For example, AntiShuffle("Hi") returns "Hi".
// AntiShuffle("hello") returns "ehllo".
// AntiShuffle("number") returns "bemnru".
// AntiShuffle("abcd") returns "abcd".
// AntiShuffle("Hello !!!Wdlor") returns "Hello !!!Wdlor".
// AntiShuffle("") returns "".
// AntiShuffle(".Hi My aemn is Meirst .Rboot How aer ?ouy") returns ".Hi My aemn is Meirst .Rboot How aer ?ouy".
func AntiShuffle(s string) string {
	strs := make([]string, 0)
	for _, i := range strings.Fields(s) {
		word := []rune(i)
		sort.Slice(word, func(i, j int) bool {
			return word[i] < word[j]
		})
		strs = append(strs, string(word))
	}
	return strings.Join(strs, "")
}

// TestAntiShuffle checks if the AntiShuffle function works correctly.
func TestAntiShuffle(t *testing.T) {
	assert := assert.New(t)
	assert.Equal("Hi", AntiShuffle("Hi"))
	assert.Equal("ehllo", AntiShuffle("hello"))
	assert.Equal("bemnru", AntiShuffle("number"))
	assert.Equal("abcd", AntiShuffle("abcd"))
	assert.Equal("Hello !!!Wdlor", AntiShuffle("Hello World!!!"))
	assert.Equal("", AntiShuffle(""))
	assert.Equal(".Hi My aemn is Meirst .Rboot How aer ?ouy", AntiShuffle("Hi. My name is Mister Robot. How are you?"))
}
