// F returns an array of integers where each element is the factorial of its index if the index is even,
// or the sum of the first `index` natural numbers if the index is odd.
//
// Examples:
// >>> F(5)
// [1 2 6 24 15]
// >>> F(7)
// [1 2 6 24 15 720 28]
// >>> F(1)
// [1]
// >>> F(3)
// [1 2 6]
func F(n int) []int {
	ret := make([]int, 0, n)
	for i := 1; i <= n; i++ {
		if i%2 == 0 {
			x := 1
			for j := 1; j <= i; j++ {
				x *= j
			}
			ret = append(ret, x)
		} else {
			x := 0
			for j := 1; j <= i; j++ {
				x += j
			}
			ret = append(ret, x)
		}
	}
	return ret
}

// TestF checks the correctness of the F function with various test cases.
func TestF(t *testing.T) {
	assert := assert.New(t)
	assert.Equal([]int{1, 2, 6, 24, 15}, F(5))
	assert.Equal([]int{1, 2, 6, 24, 15, 720, 28}, F(7))
	assert.Equal([]int{1}, F(1))
	assert.Equal([]int{1, 2, 6}, F(3))
