// >>> MatchParens([]string{"(()(())", "())())"})
// "yes"
// >>> MatchParens([]string{")())", "(()()("}))
// "yes"
// >>> MatchParens([]string{"(())))", "(()())(("}))
// "no"
// >>> MatchParens([]string{"()", "())"})
// "yes"
// >>> MatchParens([]string{")", "("})
// "no"
func MatchParens(lst []string) string {
	check := func(s string) bool {
		val := 0
		for _, i := range s {
			if i == '(' {
				val++
			} else {
				val--
			}
			if val < 0 {
				return false
			}
		}
		return val == 0
	}

	S1 := lst[0] + lst[1]
	S2 := lst[1] + lst[0]
	if check(S1) || check(S2) {
		return "yes"
	}
	return "no"
}

// TestMatchParens tests the MatchParens function with various inputs.
func TestMatchParens(t *testing.T) {
	assert := assert.New(t)
	assert.Equal("Yes", MatchParens([]string{"()(", ")"}))
	assert.Equal("No", MatchParens([]string{")", ")"}))
	assert.Equal("No", MatchParens([]string{"(()(())", "())())"}))
	assert.Equal("Yes", MatchParens([]string{")())", "(()()("}))
	assert.Equal("Yes", MatchParens([]string{"(())))", "(()())(("}))
	assert.Equal("No", MatchParens([]string{"()", "())"}))
	assert.Equal("Yes", MatchParens([]string{")", "("}))
}
