// SpecialFactorial calculates the factorial of a number and then raises it to the power of the factorial of that number.
// For example, SpecialFactorial(4) returns 288 because 4! = 24 and (24!)^2 = 288^2 = 288.
func SpecialFactorial(n int) int {
	fact_i := 1
	special_fact := 1
	for i := 1; i <= n; i++ {
		i *= n
		fact_i *= i
		special_fact *= fact_i
	}
	return special_fact
}

// TestSpecialFactorial checks the correctness of the SpecialFactorial function with various test cases.
