// FixSpaces takes a string and replaces sequences of spaces with hyphens or underscores.
// If a sequence of more than two spaces is found, it replaces them with a single hyphen.
// If a sequence of exactly two spaces is found, it replaces them with an underscore.
// Spaces at the beginning or end of the string are ignored.
//
// Examples:
// >>> FixSpaces("Example")
// "Example"
// >>> FixSpaces("Mudasir Hanif ")
// "Mudasir_Hanif_"
// >>> FixSpaces("Yellow_Yellow__Dirty__Fellow")
// "Yellow_Yellow__Dirty__Fellow"
// >>> FixSpaces("Exa-mple")
// "Exa-mple"
// >>> FixSpaces("   Exa 1 2 2 mple")
// "-Exa_1_2_2_mple"
func FixSpaces(text string) string {
	new_text := make([]byte, 0)
	i := 0
	start, end := 0, 0
	for i < len(text) {
		if text[i] == ' ' {
			end++
		} else {
			switch {
			case end - start > 2:
				new_text = append(new_text, '-')
			case end - start > 0:
				for n := 0; n < end-start; n++ {
					new_text = append(new_text, '_')
				}
			}
			new_text = append(new_text, text[i])
			start, end = i+1, i+1
		}
		i += 1
	}
	if end - start > 2 {
		new_text = append(new_text, '-')
	} else if end - start > 0 {
		new_text = append(new_text, '_')
	}
	return string(new_text)
}

func TestFixSpaces(t *testing.T) {
	assert := assert.New(t)
	assert.Equal("Example", FixSpaces("Example"))
	assert.Equal("Mudasir_Hanif_", FixSpaces("Mudasir Hanif "))
	assert.Equal("Yellow_Yellow__Dirty__Fellow", FixSpaces("Yellow Yellow  Dirty  Fellow"))
	assert.Equal("Exa-mple", FixSpaces("Exa   mple"))
	assert.Equal("-Exa_1_2_2_mple", FixSpaces("   Exa 1 2 2 mple"))
}
