// CycpatternCheck checks if string 'a' contains a cyclic pattern of string 'b'.
// A cyclic pattern is a substring that can be obtained by rotating 'b' to the left.
// For example, "xyw" is a cyclic pattern of "xyw".
//
// Examples:
// CycpatternCheck("xyzw", "xyw") returns false
// CycpatternCheck("yello", "ell") returns true
// CycpatternCheck("whattup", "ptut") returns false
// CycpatternCheck("efef", "fee") returns true
// CycpatternCheck("abab", "aabb") returns true
// CycpatternCheck("winemtt", "tinem") returns true
func CycpatternCheck(a, b string) bool {
	l := len(b)
	pat := b + b
	for i := 0; i < len(a) - l + 1; i++ {
		for j := 0; j < len(b) - l + 1; j++ {
			if a[i:i+l] == pat[j:j+l] {
				return true
			}
		}
	}
	return false
}

// TestCycpatternCheck tests the CycpatternCheck function with various inputs.
func TestCycpatternCheck(t *testing.T) {
	assert := assert.New(t)
	assert.Equal(false, CycpatternCheck("xyzw", "xyw"))
	assert.Equal(true, CycpatternCheck("yello", "ell"))
	assert.Equal(false, CycpatternCheck("whattup", "ptut"))
	assert.Equal(true, CycpatternCheck("efef", "fee"))
	assert.Equal(false, CycpatternCheck("abab", "aabb"))
	assert.Equal(true, CycpatternCheck("winemtt", "tinem"))
}
