// Eat takes three integers: number (the current amount of food), need (the amount of food needed to eat),
// and remaining (the total amount of food available). It returns two integers:
// - The first integer is the new amount of food after eating.
// - The second integer is the remaining amount of food after eating.
//
// If the need is less than or equal to the remaining amount, it returns the new amount of food
// and the remaining amount after eating.
// If the need is greater than the remaining amount, it returns the sum of the new amount of food
// and the remaining amount after eating, and sets the second integer to 0.
func Eat(number, need, remaining int) []int {
	if need <= remaining {
		return []int{number + need, number + remaining - need}
	}
	return []int{number + need + remaining, 0}
}

// TestEat tests the Eat function with various inputs.
func TestEat(t *testing.T) {
	assert := assert.New(t)
	assert.Equal([]int{11, 4}, Eat(5, 6, 10))
	assert.Equal([]int{12, 1}, Eat(4, 8, 9))
	assert.Equal([]int{11, 0}, Eat(1, 10, 10))
	assert.Equal([]int{7, 0}, Eat(2, 11, 5))
	assert.Equal([]int{9, 2}, Eat(4, 5, 7))
	assert.Equal([]int{5, 0}, Eat(4, 5, 1))
}
