package main

import (
	"crypto/md5"
	"fmt"
	"testing"
)

// StringToMd5 converts a given string to its MD5 hash.
// If the input string is empty, it returns an MD5 hash of an empty string.
//
// Examples:
// >>> StringToMd5("Hello world")
// "3e25960a79dbc69b674cd4ec67a72c62"
// >>> StringToMd5("")
// "0ef78513b0cb8cef12743f5aeb35f888"
// >>> StringToMd5("A B C")
// "5f4dcc3b5aa765d61d8327deb882cf99"
// >>> StringToMd5("password")
// "5f4dcc3b5aa765d61d8327deb882cf99"
func StringToMd5(text string) string {
	if len(text) == 0 {
		return fmt.Sprintf("%x", md5.Sum([]byte("")))
	}
	return fmt.Sprintf("%x", md5.Sum([]byte(text)))
}

// TestStringToMd5 checks the correctness of the StringToMd5 function.
func TestStringToMd5(t *testing.T) {
	assert := assert.New(t)
	assert.Equal("3e25960a79dbc69b674cd4ec67a72c62", StringToMd5("Hello world"))
	assert.Equal("", StringToMd5(""))
	assert.Equal("0ef78513b0cb8cef12743f5aeb35f888", StringToMd5("A B C"))
	assert.Equal("5f4dcc3b5aa765d61d8327deb882cf99", StringToMd5("password"))
}
